function initials(name: string | null, email: string) {
  const source = name?.trim() || email;
  return source
    .split(/[\s@._]+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((p) => p[0]!.toUpperCase())
    .join('');
}
function relativeTime(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 30) return `${days}d ago`;
  return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}
function DeltaChip({ delta }: { delta: number | null }) {
  if (delta === null || delta === undefined || Number.isNaN(delta)) return null;
  const positive = delta >= 0;
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 rounded-md px-2 py-0.5 font-mono text-[11px] font-semibold tabular-nums',
        positive
          ? 'bg-emerald-500/10 text-emerald-700 dark:bg-emerald-400/10 dark:text-emerald-300'
          : 'bg-rose-500/10 text-rose-700 dark:bg-rose-400/10 dark:text-rose-300',
      )}
    >
      <TrendingUp className={cn('h-3 w-3', !positive && 'rotate-180')} /> {positive ? '+' : ''}
      {delta.toFixed(1)}%
    </span>
  );
}
function Sparkline({ delta, positive }: { delta: number | null; positive: boolean }) {
  const points = useMemo(() => {
    const base = 8;
    const trend = delta !== null ? Math.sign(delta) * Math.min(6, Math.abs(delta) / 5) : 0;
    return Array.from({ length: 7 }, (_, i) => {
      const noise = Math.sin(i * 1.3) * 2 + (Math.random() * 2 - 1);
      return base + trend * (i / 6) * 4 + noise;
    });
  }, [delta]);
  const w = 84;
  const h = 28;
  const min = Math.min(...points);
  const max = Math.max(...points);
  const range = max - min || 1;
  const d = points
    .map((v, i) => `${(i / (points.length - 1)) * w},${h - ((v - min) / range) * (h - 6) - 3}`)
    .join(' ');
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} className="overflow-visible">
      <polyline
        fill={positive ? 'rgba(16,185,129,0.10)' : 'rgba(244,63,94,0.10)'}
        stroke="none"
        points={`${d} ${w},${h} 0,${h}`}
      />
      <polyline
        fill="none"
        stroke={positive ? '#10b981' : '#f43f5e'}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        points={d}
        style={{
          filter: `drop-shadow(0 0 6px ${positive ? 'rgba(16,185,129,0.45)' : 'rgba(244,63,94,0.45)'})`,
        }}
      />
    </svg>
  );
}
